60	stringstream Touchstone::toString(Touchstone::Scale unit, Touchstone::Format format)
61	{
62	    stringstream s;
63	    s << std::fixed << std::setprecision(12);
64	    // write option line
65	    s << "# ";
66	    switch(unit) {
67	        case Scale::Hz: s << "HZ "; break;
68	        case Scale::kHz: s << "KHZ "; break;
69	        case Scale::MHz: s << "MHZ "; break;
70	        case Scale::GHz: s << "GHZ "; break;
71	    }
72	    // only S parameters supported so far
73	    s << "S ";
74	    switch(format) {
75	        case Format::DBAngle: s << "DB "; break;
76	        case Format::RealImaginary: s << "RI "; break;
77	        case Format::MagnitudeAngle: s << "MA "; break;
78	    }
79	    // reference impedance
80	    s << "R " << referenceImpedance << "\n";
81	
82	    auto printParameter = [format](ostream &out, complex<double> &c) {
83	        switch (format) {
84	        case Format::RealImaginary:
85	            out << c.real() << " " << c.imag();
86	            break;
87	        case Format::MagnitudeAngle:
88	            out << abs(c) << " " << arg(c) / M_PI * 180.0;
89	            break;
90	        case Format::DBAngle:
91	            out << Util::SparamTodB(c) << " " << arg(c) / M_PI * 180.0;
92	            break;
93	        }
94	    };
95	
96	    for(auto p : m_datapoints) {
97	        switch(unit) {
98	            case Scale::Hz: s << p.frequency; break;
99	            case Scale::kHz: s << p.frequency / 1e3; break;
100	            case Scale::MHz: s << p.frequency / 1e6; break;
101	            case Scale::GHz: s << p.frequency / 1e9; break;
102	        }
103	        s << " ";
104	        // special cases for 1 and 2 port
105	        if (m_ports == 1) {
106	            printParameter(s, p.S[0]);
107	            s << "\n";
108	        } else if (m_ports == 2){
109	            printParameter(s, p.S[0]);
110	            // touchstone expects S11 S21 S12 S22 order, swap S12 and S21
111	            s << " ";
112	            printParameter(s, p.S[2]);
113	            s << " ";
114	            printParameter(s, p.S[1]);
115	            s << " ";
116	            printParameter(s, p.S[3]);
117	            s << "\n";
118	        } else {
119	            // print parameters in matrix form
120	            for(unsigned int i=0;i<m_ports;i++) {
121	                for(unsigned int j=0;j<m_ports;j++) {
122	                    printParameter(s, p.S[i*m_ports + j]);
123	                    if (j%4 == 3) {
124	                        s << "\n";
125	                    } else {
126	                        s << " ";
127	                    }
128	                }
129	                if(m_ports%4 != 0) {
130	                    s << "\n";
131	                }
132	            }
133	        }
134	    }
135	    return s;
136	}
