138	Touchstone Touchstone::fromFile(string filename)
139	{
140	    ifstream file;
141	    file.open(filename);
142	
143	    if(!file.is_open()) {
144	        throw runtime_error("Unable to open file:" + filename);
145	    }
146	
147	    // extract number of ports from filename
148	    auto index_extension = filename.find_last_of('.');
149	    if((filename[index_extension + 1] != 's' && filename[index_extension + 1] != 'S')
150	            || filename[index_extension+2] < '1' || filename[index_extension+2] > '9'
151	            || (filename[index_extension+3] != 'p' && filename[index_extension+3] != 'P')) {
152	        throw runtime_error("Invalid filename extension");
153	    }
154	    unsigned int ports = filename[index_extension + 2] - '0';
155	    auto ret = Touchstone(ports);
156	
157	    Scale unit = Scale::GHz;
158	    Format format = Format::RealImaginary;
159	
160	    bool option_line_found = false;
161	    unsigned int parameter_cnt = 0;
162	
163	    Datapoint point;
164	
165	    string line;
166	    unsigned int lineCnt = 0;
167	    while(getline(file, line)) {
168	        lineCnt++;
169	        // remove comments
170	        auto comment = line.find_first_of('!');
171	        if(comment != string::npos) {
172	            line.erase(comment);
173	        }
174	        // remove leading whitespace
175	        size_t first = line.find_first_not_of(" \t\r\n");
176	        if (string::npos == first) {
177	            // string does only contain whitespace, skip line
178	            continue;
179	        }
180	        line.erase(0, first);
181	
182	        if (line[0] == '#') {
183	            // this is the option line
184	            if (option_line_found) {
185	                throw runtime_error("Additional option line present");
186	            }
187	            option_line_found = true;
188	            transform(line.begin(), line.end(), line.begin(), ::toupper);
189	            // check individual options
190	            line.erase(0,1);
191	            istringstream iss(line);
192	            bool last_R = false;
193	            string s;
194	            for(;iss>>s;) {
195	                if(last_R) {
196	                    last_R = false;
197	                    // read reference impedance
198	                    ret.referenceImpedance = stod(s, nullptr);
199	                    break;
200	                }
201	                if (!s.compare("HZ")) {
202	                    unit = Scale::Hz;
203	                } else if (!s.compare("KHZ")) {
204	                    unit = Scale::kHz;
205	                } else if (!s.compare("MHZ")) {
206	                    unit = Scale::MHz;
207	                } else if (!s.compare("GHZ")) {
208	                    unit = Scale::GHz;
209	                } else if (!s.compare("S")) {
210	                    // S parameter, nothing to do
211	                } else if (!s.compare("Y")) {
212	                   throw runtime_error("Y parameters not supported");
213	                } else if (!s.compare("Z")) {
214	                    throw runtime_error("Z parameters not supported");
215	                } else if (!s.compare("G")) {
216	                    throw runtime_error("G parameters not supported");
217	                } else if (!s.compare("H")) {
218	                    throw runtime_error("H parameters not supported");
219	                } else if(!s.compare("MA")) {
220	                    format = Format::MagnitudeAngle;
221	                } else if(!s.compare("DB")) {
222	                    format = Format::DBAngle;
223	                } else if(!s.compare("RI")) {
224	                    format = Format::RealImaginary;
225	                } else if(!s.compare("R")) {
226	                    // next option is the reference impedance
227	                    last_R = true;
228	                } else {
229	                    throw runtime_error("Unexpected option in option line");
230	                }
231	            }
232	        } else {
233	            // not the option line
234	            if(!option_line_found) {
235	                throw runtime_error("First dataline before option line");
236	            }
237	            auto parseDatapoint = [format, &point, &lineCnt](istream &in) -> complex<double> {
238	                double part1, part2;
239	                if(!(in >> part1) || !(in >> part2)) {
240	                    throw runtime_error("Failed to parse parameters on line "+std::to_string(lineCnt)+" with frequency "+Unit::ToString(point.frequency,"Hz", " kMG", 10).toStdString());
241	                }
242	                complex<double> ret;
243	                switch(format) {
244	                case Format::MagnitudeAngle:
245	                    ret = polar(part1, part2 / 180.0 * M_PI);
246	                    break;
247	                case Format::DBAngle:
248	                    ret = polar(pow(10, part1/20), part2 / 180.0 * M_PI);
249	                    break;
250	                case Format::RealImaginary:
251	                    ret = complex<double>(part1, part2);
252	                    break;
253	                }
254	                return ret;
255	            };
256	            istringstream iss(line);
257	            if (parameter_cnt == 0) {
258	                iss >> point.frequency;
259	                point.S.clear();
260	                switch(unit) {
261	                    case Scale::Hz: break;
262	                    case Scale::kHz: point.frequency *= 1e3; break;
263	                    case Scale::MHz: point.frequency *= 1e6; break;
264	                    case Scale::GHz: point.frequency *= 1e9; break;
265	                }
266	            }
267	            unsigned int parameters_per_line;
268	            if(ports == 1) {
269	                parameters_per_line = 1;
270	            } else if(ports == 3) {
271	                parameters_per_line = 3;
272	            } else {
273	                parameters_per_line = 4;
274	            }
275	            unsigned int parameters_per_point = ports * ports;
276	            for(unsigned int i=0;i<parameters_per_line;i++) {
277	                point.S.push_back(parseDatapoint(iss));
278	                parameter_cnt++;
279	                if(parameter_cnt >= parameters_per_point) {
280	                    parameter_cnt = 0;
281	                    if(ports == 2) {
282	                        // 2 port touchstone has S11 S21 S12 S22 order, swap S12 and S21
283	                        swap(point.S[1], point.S[2]);
284	                    }
285	                    ret.AddDatapoint(point);
286	                    break;
287	                }
288	            }
289	        }
290	    }
291	    ret.filename = QString::fromStdString(filename);
292	    return ret;
293	}
