313	Touchstone::Datapoint Touchstone::interpolate(double frequency)
314	{
315	    if(m_datapoints.size() == 0) {
316	        throw runtime_error("Trying to interpolate empty touchstone data");
317	    }
318	    // Check if requested frequency is outside of points and return first/last datapoint respectively
319	    if(frequency <= m_datapoints.front().frequency) {
320	        return m_datapoints.front();
321	    } else if(frequency >= m_datapoints.back().frequency) {
322	        return m_datapoints.back();
323	    }
324	    // frequency within points, interpolate
325	    auto lower = lower_bound(m_datapoints.begin(), m_datapoints.end(), frequency, [](const Datapoint &lhs, double rhs) -> bool {
326	        return lhs.frequency < rhs;
327	    });
328	    auto highPoint = *lower;
329	    auto lowPoint = *prev(lower);
330	    double alpha = (frequency - lowPoint.frequency) / (highPoint.frequency - lowPoint.frequency);
331	    Datapoint ret;
332	    ret.frequency = frequency;
333	    for(unsigned int i=0;i<lowPoint.S.size();i++) {
334	        ret.S.push_back(lowPoint.S[i] * (1.0-alpha) + highPoint.S[i] * alpha);
335	    }
336	    return ret;
337	}
