339	void Touchstone::reduceTo2Port(unsigned int port1, unsigned int port2)
340	{
341	    if (port1 >= m_ports || port2 >= m_ports || port1 == port2) {
342	        throw runtime_error("Invalid port number");
343	    }
344	    unsigned int S11_index = port1 * m_ports + port1;
345	    unsigned int S22_index = port2 * m_ports + port2;
346	    unsigned int S12_index = port1 * m_ports + port2;
347	    unsigned int S21_index = port2 * m_ports + port1;
348	    if(m_ports == 2) {
349	        swap(S21_index, S12_index);
350	    }
351	    for(auto &p : m_datapoints) {
352	        auto S11 = p.S[S11_index];
353	        auto S12 = p.S[S12_index];
354	        auto S21 = p.S[S21_index];
355	        auto S22 = p.S[S22_index];
356	        p.S.clear();
357	        p.S.push_back(S11);
358	        p.S.push_back(S21);
359	        p.S.push_back(S12);
360	        p.S.push_back(S22);
361	    }
362	    m_ports = 2;
363	}
