365	void Touchstone::reduceTo1Port(unsigned int port)
366	{
367	    if (port >= m_ports) {
368	        throw runtime_error("Invalid port number");
369	    }
370	    if(m_ports == 1) {
371	        // already at one port, nothing to do
372	        return;
373	    }
374	    unsigned int S11_index = port * m_ports + port;
375	    for(auto &p : m_datapoints) {
376	        auto S11 = p.S[S11_index];
377	        p.S.clear();
378	        p.S.push_back(S11);
379	    }
380	    m_ports = 1;
381	}
