389	{
390	    nlohmann::json j;
391	    j["ports"] = m_ports;
392	    j["filename"] = filename.toStdString();
393	    if(m_datapoints.size() > 0) {
394	        nlohmann::json json_points;
395	        for(auto d : m_datapoints) {
396	            nlohmann::json point;
397	            point["frequency"] = d.frequency;
398	            nlohmann::json sparams;
399	            for(auto s : d.S) {
400	                nlohmann::json sparam;
401	                sparam["real"] = s.real();
402	                sparam["imag"] = s.imag();
403	                sparams.push_back(sparam);
404	            }
405	            point["Sparams"] = sparams;
406	            json_points.push_back(point);
407	        }
408	        j["datapoints"] = json_points;
409	    }
410	    return j;
