413	void Touchstone::fromJSON(nlohmann::json j)
414	{
415	    m_datapoints.clear();
416	    filename = QString::fromStdString(j.value("filename", ""));
417	    m_ports = j.value("ports", 0);
418	    if(!m_ports || !j.contains("datapoints")) {
419	        return;
420	    }
421	    auto json_points = j["datapoints"];
422	    for(auto point : json_points) {
423	        Datapoint d;
424	        if(!point.contains("frequency") || !point.contains("Sparams")) {
425	            // missing data, abort here
426	            qWarning() << "Touchstone data point does not contain frequency or S parameters";
427	            break;
428	        }
429	        d.frequency = point["frequency"];
430	        if(point["Sparams"].size() != m_ports * m_ports) {
431	            // invalid number of Sparams, abort here
432	            qWarning() << "Invalid number of S parameters, got" << point["Sparams"].size() << "expected" << m_ports*m_ports;
433	            break;
434	        }
435	        for(auto Sparam : point["Sparams"]) {
436	            d.S.push_back(complex<double>(Sparam.value("real", 0.0), Sparam.value("imag", 0.0)));
437	        }
438	        m_datapoints.push_back(d);
439	    }
440	}
