15	TraceCSVExport::TraceCSVExport(TraceModel &traceModel, QWidget *parent) :
16	    QDialog(parent),
17	    ui(new Ui::TraceCSVExport),
18	    model(traceModel.getTraces())
19	{
20	    ui->setupUi(this);
21	    ui->listView->setModel(&model);
22	    ui->buttonBox->button(QDialogButtonBox::Ok)->setEnabled(false);
23	    connect(&model, &TraceCSVModel::selectionChanged, ui->buttonBox->button(QDialogButtonBox::Ok), &QPushButton::setEnabled);
24	    connect(&model, &TraceCSVModel::selectionChanged, [&](){
25	        auto traces = model.tracesToExport();
26	        if(traces.size() == 0) {
27	            ui->listColumns->clear();
28	        } else if(ui->listColumns->count() == 0) {
29	            // first trace has been selected, fill column selection
30	            auto t = traces.front();
31	            auto domain = t->outputType();
32	            auto Xaxis = XAxis::Type::Last;
33	            switch(domain) {
34	            case Trace::DataType::Invalid:
35	            case Trace::DataType::Frequency: Xaxis = XAxis::Type::Frequency; break;
36	            case Trace::DataType::Power: Xaxis = XAxis::Type::Power; break;
37	            case Trace::DataType::Time: Xaxis = XAxis::Type::Time; break;
38	            case Trace::DataType::TimeZeroSpan: Xaxis = XAxis::Type::TimeZeroSpan; break;
39	            }
40	            if(Xaxis == XAxis::Type::Last) {
41	                // invalid axis selection
42	                return;
43	            }
44	            for(auto ytype : YAxis::getSupported(Xaxis, traceModel.getSource())) {
45	                if(ytype != YAxis::Type::Disabled) {
46	                    auto item = new QListWidgetItem(YAxis::TypeToName(ytype), ui->listColumns);
47	                    item->setCheckState(Qt::Unchecked);
48	                }
49	            }
50	            // first fill of selection, nothing selected yet, disable OK button
51	            ui->buttonBox->button(QDialogButtonBox::Ok)->setEnabled(false);
52	        }
53	    });
54	    connect(ui->listColumns, &QListWidget::itemChanged, this, &TraceCSVExport::columnSelectionChanged);
55	}
56	
57	TraceCSVExport::~TraceCSVExport()
58	{
59	    delete ui;
60	}
61	
62	void TraceCSVExport::columnSelectionChanged()
63	{
64	    auto types = getSelectedYAxisTypes();
65	    ui->buttonBox->button(QDialogButtonBox::Ok)->setEnabled(types.size() > 0);
66	}
67	
68	void TraceCSVExport::on_buttonBox_accepted()
69	{
70	    auto traces = model.tracesToExport();
71	    if(traces.size() == 0) {
72	        return;
73	    }
74	
75	    auto filename = QFileDialog::getSaveFileName(nullptr, "Save calibration data", Preferences::getInstance().UISettings.Paths.data, "CSV files (*.csv)", nullptr, Preferences::QFileDialogOptions());
76	    if(filename.isEmpty()) {
77	        // aborted selection
78	        return;
79	    }
80	    Preferences::getInstance().UISettings.Paths.data = QFileInfo(filename).path();
81	    if(!filename.endsWith(".csv")) {
82	        filename.append(".csv");
83	    }
84	
85	    CSV csv;
86	    // create the first column (X data)
87	    vector<double> X;
88	    QString Xname = Trace::dataTypeToString(traces[0]->outputType());
89	    auto samples = traces[0]->numSamples();
90	    for(unsigned int i=0;i<samples;i++) {
91	        X.push_back(traces[0]->sample(i).x);
92	    }
93	    csv.addColumn(Xname, X);
94	    // add the trace data
95	    for(auto trace : traces) {
96	        for(auto ytype : getSelectedYAxisTypes()) {
97	            auto axis = YAxis();
98	            axis.set(ytype, false, false, 0, 1, 10, false);
99	            auto samples = trace->numSamples();
100	            vector<double> values;
101	            for(unsigned int i=0;i<samples;i++) {
102	                values.push_back(axis.sampleToCoordinate(trace->sample(i), trace, i));
103	            }
104	            csv.addColumn(trace->name()+"_"+axis.TypeToName(), values);
105	        }
106	    }
107	
108	    csv.toFile(filename);
109	}
110	
111	std::vector<YAxis::Type> TraceCSVExport::getSelectedYAxisTypes()
112	{
113	    std::vector<YAxis::Type> ret;
114	    for(int i=0;i<ui->listColumns->count();i++) {
115	        auto item = ui->listColumns->item(i);
116	        if(item->checkState() == Qt::Checked) {
117	            auto type = YAxis::TypeFromName(item->text());
118	            ret.push_back(type);
119	        }
120	    }
121	    return ret;
122	}
123	
124	TraceCSVModel::TraceCSVModel(std::vector<Trace *> traces, QObject *parent)
125	    : QAbstractListModel(parent)
126	{
127	    this->traces = traces;
128	    save.resize(traces.size(), false);
129	    enabled.resize(traces.size(), true);
130	    points = 0;
131	    minX = maxX = 0;
132	    updateEnabledTraces();
133	}
134	
135	int TraceCSVModel::rowCount(const QModelIndex &parent) const
136	{
137	    Q_UNUSED(parent);
138	    return traces.size();
139	}
140	
141	QVariant TraceCSVModel::data(const QModelIndex &index, int role) const
142	{
143	    if(!index.isValid()) {
144	        return QVariant();
145	    }
146	    switch(role) {
147	    case Qt::CheckStateRole:
148	        if(save[index.row()]) {
149	            return Qt::Checked;
150	        } else {
151	            return Qt::Unchecked;
152	        }
153	    case Qt::DisplayRole:
154	        return traces[index.row()]->name();
155	    default:
156	        return QVariant();
157	    }
158	}
159	
160	bool TraceCSVModel::setData(const QModelIndex &index, const QVariant &value, int role)
161	{
162	    if(!index.isValid()) {
163	        return false;
164	    }
165	    if(role==Qt::CheckStateRole) {
166	        save[index.row()] = !save[index.row()];
167	        updateEnabledTraces();
168	        return true;
169	    } else {
170	        return QAbstractItemModel::setData(index, value, role);
171	    }
172	}
173	
174	Qt::ItemFlags TraceCSVModel::flags(const QModelIndex &index) const
175	{
176	    unsigned int flags = Qt::ItemIsUserCheckable;
177	    if(index.isValid()) {
178	        if(enabled[index.row()]) {
179	            flags |= Qt::ItemIsEnabled;
180	        }
181	    }
182	    return (Qt::ItemFlags) flags;
183	}
184	
185	std::vector<Trace *> TraceCSVModel::tracesToExport()
186	{
187	    vector<Trace*> ret;
188	    for(unsigned int i=0;i<traces.size();i++) {
189	        if(save[i]) {
190	            ret.push_back(traces[i]);
191	        }
192	    }
193	    return ret;
194	}
195	
196	void TraceCSVModel::updateEnabledTraces()
197	{
198	    beginResetModel();
199	    // find first selected trace and use its settings
200	    points = 0;
201	    type = Trace::DataType::Invalid;
202	    for(unsigned int i=0;i<traces.size();i++) {
203	        if(save[i]) {
204	            points = traces[i]->numSamples();
205	            minX = traces[i]->minX();
206	            maxX = traces[i]->maxX();
207	            type = traces[i]->outputType();
208	        }
209	    }
210	    // second pass: compare to the settings and only enable identical traces
211	    for(unsigned int i=0;i<traces.size();i++) {
212	        auto enableTrace = true;
213	        if(traces[i]->numSamples() == 0 || traces[i]->outputType() == Trace::DataType::Invalid) {
214	            // trace has no valid data, unable to export
215	            enableTrace = false;
216	        }
217	        if(points > 0 && type != Trace::DataType::Invalid) {
218	            // check if this trace matches the already selected one
219	            if((traces[i]->numSamples() != points)
220	                    || (traces[i]->minX() != minX)
221	                    || (traces[i]->maxX() != maxX)
222	                    || (traces[i]->outputType() != type)) {
223	                // different settings, not possible to export in this combination
224	                enableTrace = false;
225	            }
226	        }
227	        enabled[i] = enableTrace;
228	        if(!enableTrace) {
229	            save[i] = false;
230	        }
231	    }
232	    endResetModel();
233	    emit selectionChanged(points > 0);
234	}
